<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/email.php';requireLogin('../login.php');requireRole('super_admin','../login.php');$pdo=Database::getInstance();
$defaults=['gmail'=>['smtp.gmail.com','587','tls'],'zoho'=>['smtp.zoho.com','587','tls'],'custom'=>['','587','tls']];
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=(string)($_POST['action']??'');
 if($action==='provider_defaults'){ $p=(string)($_POST['provider']??'custom');$d=$defaults[$p]??$defaults['custom'];foreach(['email_provider'=>$p,'smtp_host'=>$d[0],'smtp_port'=>$d[1],'smtp_encryption'=>$d[2],'email_smtp_validated'=>'0','email_service_enabled'=>'0'] as $k=>$v)setSetting($pdo,$k,$v);setFlash('success','প্রোভাইডার ডিফল্ট সেট হয়েছে।');redirect('settings.php');}
 if($action==='save'){ $provider=(string)($_POST['provider']??'custom');$allowed=['gmail','zoho','custom'];$host=trim((string)($_POST['smtp_host']??''));$port=(int)($_POST['smtp_port']??0);$enc=(string)($_POST['smtp_encryption']??'tls');$user=trim((string)($_POST['smtp_username']??''));$pass=(string)($_POST['smtp_password']??'');$from=trim((string)($_POST['smtp_from_email']??''));$name=trim((string)($_POST['smtp_from_name']??APP_NAME));if(!in_array($provider,$allowed,true)||$host===''||$port<1||$port>65535||!in_array($enc,['tls','ssl','none'],true)||!filter_var($user,FILTER_VALIDATE_EMAIL)||!filter_var($from,FILTER_VALIDATE_EMAIL)||($pass===''&&getSetting('smtp_password','')==='')){setFlash('danger','SMTP তথ্য সঠিকভাবে পূরণ করুন।');redirect('settings.php');}foreach(['email_provider'=>$provider,'smtp_host'=>$host,'smtp_port'=>(string)$port,'smtp_encryption'=>$enc,'smtp_username'=>$user,'smtp_from_email'=>$from,'smtp_from_name'=>$name,'email_smtp_validated'=>'0','email_service_enabled'=>'0'] as $k=>$v)setSetting($pdo,$k,$v);if($pass!=='')setSetting($pdo,'smtp_password',$pass);setFlash('success','SMTP সেটিংস সংরক্ষিত হয়েছে। এখন টেস্ট ইমেইল পাঠান।');redirect('settings.php');}
 if($action==='test'){ $to=trim((string)($_POST['test_email']??''));$ok=filter_var($to,FILTER_VALIDATE_EMAIL)&&sendSmtpMail($to,APP_NAME.' SMTP test','<p>SMTP test successful.</p>',getMailConfig());setSetting($pdo,'email_smtp_validated',$ok?'1':'0');setFlash($ok?'success':'danger',$ok?'SMTP টেস্ট সফল হয়েছে। এখন Email Service চালু করতে পারবেন।':'SMTP টেস্ট ব্যর্থ হয়েছে। হোস্ট/পোর্ট/অ্যাপ পাসওয়ার্ড যাচাই করুন।');redirect('settings.php');}
 if($action==='toggle'){if(getSetting('email_smtp_validated','0')!=='1'){setFlash('danger','সফল SMTP টেস্ট ছাড়া Email Service চালু করা যাবে না।');}else{setSetting($pdo,'email_service_enabled',getSetting('email_service_enabled','0')==='1'?'0':'1');setFlash('success','Email Service-এর অবস্থা পরিবর্তন হয়েছে।');}redirect('settings.php');}}
$rows=$pdo->query('SELECT setting_key,setting_value FROM settings')->fetchAll();$s=[];foreach($rows as $r)$s[(string)$r['setting_key']]=(string)($r['setting_value']??'');$flash=getFlash();$active=getSetting('email_service_enabled','0')==='1';$validated=getSetting('email_smtp_validated','0')==='1';
?><!doctype html><html lang="bn"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ইমেইল সেটিংস</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="d-flex justify-content-between mb-4"><h2>ইমেইল ও 2FA সেটিংস</h2><a href="index.php" class="btn btn-outline-secondary">ড্যাশবোর্ড</a></div><?php if($flash):?><div class="alert alert-<?=e((string)$flash['type'])?>"><?=e((string)$flash['message'])?></div><?php endif;?><div class="alert alert-<?=$active?'success':'warning'?>">Email Service: <strong><?=$active?'ON':'OFF'?></strong> · SMTP যাচাই: <strong><?=$validated?'সফল':'বাকি'?></strong> · Email Service OFF থাকলে ব্যবহারকারীর 2FA সক্রিয় করা যাবে না।</div><form method="post" class="card card-body mb-4"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="save"><div class="row g-3"><div class="col-md-4"><label>Provider</label><select class="form-select" name="provider"><option value="gmail" <?=$s['email_provider']??''==='gmail'?'selected':''?>>Gmail</option><option value="zoho" <?=$s['email_provider']??''==='zoho'?'selected':''?>>Zoho</option><option value="custom" <?=$s['email_provider']??''==='custom'?'selected':''?>>Custom SMTP</option></select></div><div class="col-md-8"><label>SMTP Host</label><input class="form-control" name="smtp_host" value="<?=e($s['smtp_host']??'')?>" required></div><div class="col-md-3"><label>Port</label><input class="form-control" name="smtp_port" value="<?=e($s['smtp_port']??'587')?>" required></div><div class="col-md-3"><label>Encryption</label><select class="form-select" name="smtp_encryption"><option value="tls">TLS</option><option value="ssl">SSL</option><option value="none">None</option></select></div><div class="col-md-6"><label>Username</label><input class="form-control" type="email" name="smtp_username" value="<?=e($s['smtp_username']??'')?>" required></div><div class="col-md-6"><label>App Password</label><input class="form-control" type="password" name="smtp_password" autocomplete="new-password"><small>আগের পাসওয়ার্ড অপরিবর্তিত রাখতে ফাঁকা রাখুন।</small></div><div class="col-md-3"><label>From Email</label><input class="form-control" type="email" name="smtp_from_email" value="<?=e($s['smtp_from_email']??'')?>" required></div><div class="col-md-3"><label>From Name</label><input class="form-control" name="smtp_from_name" value="<?=e($s['smtp_from_name']??APP_NAME)?>"></div><div class="col-12"><button class="btn btn-primary">সেটিংস সংরক্ষণ</button></div></div></form><form method="post" class="card card-body mb-3"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="test"><label>Test recipient</label><div class="input-group"><input class="form-control" type="email" name="test_email" required><button class="btn btn-outline-primary">SMTP Test</button></div></form><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="toggle"><button class="btn btn-<?=$active?'danger':'success'?>"><?=$active?'Email Service বন্ধ করুন':'Email Service চালু করুন'?></button></form></main></body></html>
